1	import { Result } from "better-result";
2	import { ChevronDown, Search } from "lucide-solid";
3	import { For, Show, createEffect, createMemo, createSignal, onCleanup, onMount } from "solid-js";
4	import { useI18n } from "../i18n";
5	import { type InstalledApp, getCachedInstalledApps, listInstalledApps } from "../lib/commands/apps";
6	import {
7		type AppDictionary,
8		addAppDictionaryWord,
9		deleteAppDictionary,
10		deleteAppDictionaryWord,
11		listAppDictionaries,
12		updateAppDictionaryWord,
13	} from "../lib/commands/dictionary";
14	import { capture } from "../lib/posthog";
15	
16	const SKELETON_ROWS = Array.from({ length: 4 });
17	
18	export default function DictionaryPerApp() {
19		const [t] = useI18n();
20		const cachedApps = getCachedInstalledApps();
21		const [installedApps, setInstalledApps] = createSignal<InstalledApp[]>(cachedApps ?? []);
22		const [appDicts, setAppDicts] = createSignal<AppDictionary[]>([]);
23		const [pendingApps, setPendingApps] = createSignal<AppDictionary[]>([]);
24		const [appsLoading, setAppsLoading] = createSignal(cachedApps === null);
25	
26		const [searchQuery, setSearchQuery] = createSignal("");
27		const [searchOpen, setSearchOpen] = createSignal(false);
28		const [highlightedIndex, setHighlightedIndex] = createSignal(0);
29	
30		const [expanded, setExpanded] = createSignal<Set<string>>(new Set());
31		const [newWordByApp, setNewWordByApp] = createSignal<Record<string, string>>({});
32		const [addingApp, setAddingApp] = createSignal<Set<string>>(new Set());
33		const [editingAppWordId, setEditingAppWordId] = createSignal<string | null>(null);
34		const [editingAppWord, setEditingAppWord] = createSignal("");
35	
36		let searchContainerRef: HTMLDivElement | undefined;
37		const optionRefs = new Map<number, HTMLButtonElement>();
38	
39		const fetchAppDicts = async () => {
40			const result = await listAppDictionaries();
41			if (Result.isOk(result)) setAppDicts(result.value);
42		};
43	
44		onMount(async () => {
45			capture("$pageview", { $current_url: "/dictionary/per-app" });
46			const apps = await listInstalledApps();
47			if (Result.isOk(apps)) setInstalledApps(apps.value);
48			else console.error("Failed to load installed apps", apps.error);
49			const dicts = await listAppDictionaries();
50			if (Result.isOk(dicts)) setAppDicts(dicts.value);
51			else console.error("Failed to load app dictionaries", dicts.error);
52			setAppsLoading(false);
53		});
54	
55		const allAppGroups = createMemo(() => {
56			const persisted = appDicts();
57			const persistedIds = new Set(persisted.map((d) => d.bundle_id));
58			const pending = pendingApps().filter((p) => !persistedIds.has(p.bundle_id));
59			return [...persisted, ...pending];
60		});
61	
62		const configuredBundleIds = createMemo(() => new Set(allAppGroups().map((d) => d.bundle_id)));
63	
64		const iconByBundleId = createMemo(() => {
65			const map = new Map<string, string>();
66			for (const app of installedApps()) {
67				if (app.icon_data_url) map.set(app.bundle_id, app.icon_data_url);
68			}
69			return map;
70		});
71	
72		const filteredApps = createMemo(() => {
73			const query = searchQuery().trim().toLowerCase();
74			const configured = configuredBundleIds();
75			return installedApps()
76				.filter((app) => !configured.has(app.bundle_id))
77				.filter((app) => {
78					if (!query) return true;
79					return (
80						app.name.toLowerCase().includes(query) || app.bundle_id.toLowerCase().includes(query)
81					);
82				})
83				.slice(0, 50);
84		});
85	
86		createEffect(() => {
87			filteredApps();
88			searchQuery();
89			setHighlightedIndex(0);
90		});
91	
92		createEffect(() => {
93			if (!searchOpen()) return;
94			const el = optionRefs.get(highlightedIndex());
95			el?.scrollIntoView({ block: "nearest" });
96		});
97	
98		const handleClickOutside = (e: MouseEvent) => {
99			if (searchContainerRef && !searchContainerRef.contains(e.target as Node)) {
100				setSearchOpen(false);
101			}
102		};
103	
104		createEffect(() => {
105			if (searchOpen()) {
106				document.addEventListener("click", handleClickOutside);
107			} else {
108				document.removeEventListener("click", handleClickOutside);
109			}
110		});
111	
112		onCleanup(() => {
113			document.removeEventListener("click", handleClickOutside);
114		});
115	
116		const handleSearchKeyDown = (e: KeyboardEvent) => {
117			const items = filteredApps();
118			if (e.key === "ArrowDown") {
119				e.preventDefault();
120				setSearchOpen(true);
121				if (items.length === 0) return;
122				setHighlightedIndex((i) => Math.min(items.length - 1, i + 1));
123			} else if (e.key === "ArrowUp") {
124				e.preventDefault();
125				if (items.length === 0) return;
126				setHighlightedIndex((i) => Math.max(0, i - 1));
127			} else if (e.key === "Enter") {
128				if (!searchOpen() || items.length === 0) return;
129				e.preventDefault();
130				const idx = Math.min(highlightedIndex(), items.length - 1);
131				const target = items[idx];
132				if (target) handleAddApp(target);
133			} else if (e.key === "Escape") {
134				if (!searchOpen()) return;
135				e.preventDefault();
136				setSearchOpen(false);
137			}
138		};
139	
140		const handleAddApp = (app: InstalledApp) => {
141			setPendingApps((prev) => [
142				...prev,
143				{ bundle_id: app.bundle_id, app_name: app.name, words: [] },
144			]);
145			setExpanded((prev) => {
146				const next = new Set(prev);
147				next.add(app.bundle_id);
148				return next;
149			});
150			setSearchQuery("");
151			setSearchOpen(false);
152			capture("app_dictionary_app_added");
153		};
154	
155		const toggleExpanded = (bundleId: string) => {
156			setExpanded((prev) => {
157				const next = new Set(prev);
158				if (next.has(bundleId)) next.delete(bundleId);
159				else next.add(bundleId);
160				return next;
161			});
162		};
163	
164		const handleAddAppWord = async (group: AppDictionary) => {
165			const word = (newWordByApp()[group.bundle_id] ?? "").trim();
166			if (!word) return;
167			if (addingApp().has(group.bundle_id)) return;
168	
169			setAddingApp((prev) => {
170				const next = new Set(prev);
171				next.add(group.bundle_id);
172				return next;
173			});
174			const result = await addAppDictionaryWord(group.bundle_id, group.app_name, word);
175			if (Result.isOk(result)) {
176				capture("app_dictionary_word_added");
177				setNewWordByApp((prev) => ({ ...prev, [group.bundle_id]: "" }));
178				setPendingApps((prev) => prev.filter((p) => p.bundle_id !== group.bundle_id));
179				await fetchAppDicts();
180			}
181			setAddingApp((prev) => {
182				const next = new Set(prev);
183				next.delete(group.bundle_id);
184				return next;
185			});
186		};
187	
188		const handleAppWordKeyDown = (e: KeyboardEvent, group: AppDictionary) => {
189			if (e.key === "Enter") handleAddAppWord(group);
190		};
191	
192		const startEditAppWord = (wordId: string, word: string) => {
193			setEditingAppWordId(wordId);
194			setEditingAppWord(word);
195		};
196	
197		const cancelEditAppWord = () => {
198			setEditingAppWordId(null);
199			setEditingAppWord("");
200		};
201	
202		const handleEditAppWord = async (group: AppDictionary, wordId: string) => {
203			const word = editingAppWord().trim();
204			if (!word) return;
205			capture("app_dictionary_word_edited");
206			setAppDicts(
207				appDicts().map((g) =>
208					g.bundle_id === group.bundle_id
209						? { ...g, words: g.words.map((w) => (w.id === wordId ? { ...w, word } : w)) }
210						: g
211				)
212			);
213			setEditingAppWordId(null);
214			setEditingAppWord("");
215			const result = await updateAppDictionaryWord(wordId, word);
216			if (Result.isError(result)) await fetchAppDicts();
217		};
218	
219		const handleEditAppWordKeyDown = (e: KeyboardEvent, group: AppDictionary, wordId: string) => {
220			if (e.key === "Enter") handleEditAppWord(group, wordId);
221			else if (e.key === "Escape") cancelEditAppWord();
222		};
223	
224		const handleDeleteAppWord = async (group: AppDictionary, wordId: string) => {
225			capture("app_dictionary_word_deleted");
226			setAppDicts(
227				appDicts().map((g) =>
228					g.bundle_id === group.bundle_id
229						? { ...g, words: g.words.filter((w) => w.id !== wordId) }
230						: g
231				)
232			);
233			const result = await deleteAppDictionaryWord(wordId);
234			if (Result.isError(result)) await fetchAppDicts();
235		};
236	
237		const handleRemoveApp = async (group: AppDictionary) => {
238			capture("app_dictionary_app_removed");
239			setPendingApps((prev) => prev.filter((p) => p.bundle_id !== group.bundle_id));
240			setAppDicts((prev) => prev.filter((g) => g.bundle_id !== group.bundle_id));
241			setExpanded((prev) => {
242				const next = new Set(prev);
243				next.delete(group.bundle_id);
244				return next;
245			});
246			if (group.words.length > 0) {
247				const result = await deleteAppDictionary(group.bundle_id);
248				if (Result.isError(result)) await fetchAppDicts();
249			}
250		};
251	
252		return (
253			<div>
254				<div class="mb-4 flex items-center justify-between">
255					<p class="text-txt-muted font-mono text-xs">{t("dictionary.perAppDescription")}</p>
256					<Show when={allAppGroups().length > 0}>
257						<span class="text-txt-muted font-mono text-xs uppercase">
258							{t("appInstructions.appCount").replace("{count}", String(allAppGroups().length))}
259						</span>
260					</Show>
261				</div>
262	
263				<div ref={searchContainerRef} class="relative mb-6">
264					<div class="bg-th-surface border border-border p-4">
265						<div class="flex items-center gap-3">
266							<Search class="w-4 h-4 text-txt-muted shrink-0" />
267							<input
268								type="text"
269								value={searchQuery()}
270								onInput={(e) => {
271									setSearchQuery(e.currentTarget.value);
272									setSearchOpen(true);
273								}}
274								onFocus={() => setSearchOpen(true)}
275								onKeyDown={handleSearchKeyDown}
276								placeholder={t("appInstructions.searchPlaceholder")}
277								class="flex-1 bg-transparent text-txt-primary font-mono placeholder-txt-muted focus:outline-none"
278							/>
279						</div>
280					</div>
281	
282					<Show when={searchOpen()}>
283						<div class="absolute z-50 w-full mt-1 bg-th-surface border border-border-strong max-h-72 overflow-auto">
284							<Show
285								when={!appsLoading()}
286								fallback={<For each={SKELETON_ROWS}>{() => <AppRowSkeleton />}</For>}
287							>
288								<Show
289									when={filteredApps().length > 0}
290									fallback={
291										<div class="px-4 py-3 font-mono text-xs text-txt-muted uppercase tracking-wide">
292											{installedApps().length === 0
293												? t("appInstructions.noAppsDetected")
294												: t("appInstructions.noMatches")}
295										</div>
296									}
297								>
298									<For each={filteredApps()}>
299										{(app, index) => (
300											<button
301												type="button"
302												ref={(el) => optionRefs.set(index(), el)}
303												onClick={() => handleAddApp(app)}
304												onMouseEnter={() => setHighlightedIndex(index())}
305												class={`w-full px-4 py-2.5 text-left transition-colors font-mono text-sm flex items-center gap-3 ${
306													highlightedIndex() === index() ? "bg-th-hover" : ""
307												}`}
308											>
309												<AppIcon src={app.icon_data_url} alt={app.name} />
310												<div class="flex flex-col gap-0.5 min-w-0 flex-1">
311													<span class="text-txt-primary truncate">{app.name}</span>
312													<span class="text-txt-muted text-xs truncate">{app.bundle_id}</span>
313												</div>
314											</button>
315										)}
316									</For>
317								</Show>
318							</Show>
319						</div>
320					</Show>
321				</div>
322	
323				<Show when={appsLoading()}>
324					<div class="space-y-1">
325						<For each={SKELETON_ROWS}>{() => <AppRowSkeleton bordered />}</For>
326					</div>
327				</Show>
328	
329				<Show when={!appsLoading() && allAppGroups().length === 0}>
330					<div class="bg-th-surface border border-border p-12 flex flex-col items-center justify-center text-center">
331						<div class="font-mono text-txt-muted text-sm mb-4">
332							<span class="text-ac">[INFO]</span> NO_APPS_CONFIGURED
333						</div>
334						<p class="text-txt-secondary font-mono text-xs uppercase tracking-wide">
335							{t("dictionary.perAppEmptyState")}
336						</p>
337						<p class="text-txt-muted font-mono text-xs mt-2 max-w-sm">
338							{t("dictionary.perAppEmptyStateDescription")}
339						</p>
340					</div>
341				</Show>
342	
343				<Show when={!appsLoading() && allAppGroups().length > 0}>
344					<div class="space-y-1">
345						<For each={allAppGroups()}>
346							{(group) => {
347								const isOpen = () => expanded().has(group.bundle_id);
348								const wordValue = () => newWordByApp()[group.bundle_id] ?? "";
349								const isAdding = () => addingApp().has(group.bundle_id);
350								return (
351									<div class="bg-th-surface border border-border group hover:border-border-strong transition-colors">
352										<div class="flex items-stretch">
353											<button
354												type="button"
355												onClick={() => toggleExpanded(group.bundle_id)}
356												class="flex-1 px-4 py-3 flex items-center gap-3 text-left min-w-0"
357												title={isOpen() ? t("dictionary.collapse") : t("dictionary.expand")}
358											>
359												<AppIcon
360													src={iconByBundleId().get(group.bundle_id) ?? null}
361													alt={group.app_name}
362												/>
363												<div class="flex flex-col min-w-0 flex-1">
364													<span class="text-txt-primary font-mono truncate">{group.app_name}</span>
365													<span class="text-txt-muted font-mono text-xs truncate">
366														{group.bundle_id}
367													</span>
368												</div>
369												<span class="text-txt-muted font-mono text-xs uppercase tracking-wider shrink-0">
370													{t("dictionary.wordCount").replace("{count}", String(group.words.length))}
371												</span>
372												<ChevronDown
373													class={`w-4 h-4 text-txt-muted shrink-0 transition-transform ${
374														isOpen() ? "rotate-180" : ""
375													}`}
376												/>
377											</button>
378											<button
379												type="button"
380												onClick={() => handleRemoveApp(group)}
381												class="px-3 flex items-center text-txt-muted hover:text-ac opacity-0 group-hover:opacity-100 transition-all font-mono text-xs uppercase tracking-wider shrink-0"
382												title={t("appInstructions.delete")}
383											>
384												[DEL]
385											</button>
386										</div>
387										<Show when={isOpen()}>
388											<div class="border-t border-border px-4 py-3 space-y-2">
389												<div class="flex gap-2">
390													<input
391														type="text"
392														value={wordValue()}
393														onInput={(e) =>
394															setNewWordByApp((prev) => ({
395																...prev,
396																[group.bundle_id]: e.currentTarget.value,
397															}))
398														}
399														onKeyDown={(e) => handleAppWordKeyDown(e, group)}
400														placeholder={t("dictionary.wordPlaceholder")}
401														class="flex-1 px-3 py-1.5 bg-th-input border border-border-strong text-txt-primary font-mono text-sm placeholder-txt-muted focus:outline-none focus:border-ac transition-colors"
402													/>
403													<button
404														type="button"
405														onClick={() => handleAddAppWord(group)}
406														disabled={!wordValue().trim() || isAdding()}
407														class="flex items-center gap-1 px-3 py-1.5 bg-ac text-ac-on font-mono uppercase tracking-wider text-xs hover:bg-ac-hover disabled:opacity-50 transition-colors"
408													>
409														<span>+</span>
410														{t("dictionary.addWord")}
411													</button>
412												</div>
413	
414												<Show when={group.words.length > 0}>
415													<div class="space-y-1 pt-1">
416														<For each={group.words}>
417															{(word) => (
418																<div class="px-3 py-2 bg-th-input border border-border flex items-center justify-between gap-2 group/word">
419																	<Show
420																		when={editingAppWordId() === word.id}
421																		fallback={
422																			<span class="text-txt-primary font-mono text-sm flex-1 min-w-0 truncate">
423																				{word.word}
424																			</span>
425																		}
426																	>
427																		<input
428																			type="text"
429																			value={editingAppWord()}
430																			onInput={(e) => setEditingAppWord(e.currentTarget.value)}
431																			onKeyDown={(e) => handleEditAppWordKeyDown(e, group, word.id)}
432																			class="flex-1 px-2 py-1 bg-th-base border border-border-strong text-txt-primary font-mono text-sm focus:outline-none focus:border-ac transition-colors"
433																			autofocus
434																		/>
435																	</Show>
436																	<div class="flex items-center gap-2 font-mono text-xs shrink-0">
437																		<Show
438																			when={editingAppWordId() === word.id}
439																			fallback={
440																				<>
441																					<button
442																						type="button"
443																						onClick={() => startEditAppWord(word.id, word.word)}
444																						class="text-txt-muted hover:text-ac opacity-0 group-hover/word:opacity-100 transition-all uppercase tracking-wider"
445																						title={t("dictionary.edit")}
446																					>
447																						[EDIT]
448																					</button>
449																					<button
450																						type="button"
451																						onClick={() => handleDeleteAppWord(group, word.id)}
452																						class="text-txt-muted hover:text-ac opacity-0 group-hover/word:opacity-100 transition-all uppercase tracking-wider"
453																						title={t("dictionary.delete")}
454																					>
455																						[DEL]
456																					</button>
457																				</>
458																			}
459																		>
460																			<button
461																				type="button"
462																				onClick={() => handleEditAppWord(group, word.id)}
463																				class="text-success hover:opacity-80 uppercase tracking-wider"
464																				title={t("dictionary.save")}
465																			>
466																				[SAVE]
467																			</button>
468																			<button
469																				type="button"
470																				onClick={cancelEditAppWord}
471																				class="text-txt-muted hover:text-txt-secondary uppercase tracking-wider"
472																				title={t("dictionary.cancel")}
473																			>
474																				[CANCEL]
475																			</button>
476																		</Show>
477																	</div>
478																</div>
479															)}
480														</For>
481													</div>
482												</Show>
483											</div>
484										</Show>
485									</div>
486								);
487							}}
488						</For>
489					</div>
490				</Show>
491			</div>
492		);
493	}
494	
495	interface AppRowSkeletonProps {
496		bordered?: boolean;
497	}
498	
499	function AppRowSkeleton(props: AppRowSkeletonProps) {
500		return (
501			<div
502				class={`px-4 py-2.5 flex items-center gap-3 animate-pulse ${
503					props.bordered ? "bg-th-surface border border-border" : ""
504				}`}
505			>
506				<div class="w-8 h-8 shrink-0 bg-th-input" />
507				<div class="flex flex-col gap-1.5 min-w-0 flex-1">
508					<div class="h-3 w-32 bg-th-input" />
509					<div class="h-2.5 w-48 bg-th-input opacity-60" />
510				</div>
511				<Show when={props.bordered}>
512					<div class="w-20 h-4 bg-th-input shrink-0" />
513				</Show>
514			</div>
515		);
516	}
517	
518	interface AppIconProps {
519		src: string | null;
520		alt: string;
521	}
522	
523	function AppIcon(props: AppIconProps) {
524		return (
525			<Show
526				when={props.src}
527				fallback={
528					<div class="w-8 h-8 shrink-0 bg-th-input border border-border flex items-center justify-center text-txt-muted font-mono text-xs">
529						{props.alt.charAt(0).toUpperCase()}
530					</div>
531				}
532			>
533				{(src) => <img src={src()} alt={props.alt} class="w-8 h-8 shrink-0" draggable={false} />}
534			</Show>
535		);
536	}
