1	import { Result } from "better-result";
2	import { ChevronDown } from "lucide-solid";
3	import { For, Show, createMemo, createSignal, onMount } from "solid-js";
4	import AddSiteForm from "../components/AddSiteForm";
5	import SiteIcon from "../components/SiteIcon";
6	import { useI18n } from "../i18n";
7	import {
8		type SiteDictionary,
9		addSiteDictionaryWord,
10		deleteSiteDictionary,
11		deleteSiteDictionaryWord,
12		listSiteDictionaries,
13		updateSiteDictionaryWord,
14	} from "../lib/commands/dictionary";
15	import { preloadFavicons } from "../lib/favicons";
16	import { capture } from "../lib/posthog";
17	
18	export default function DictionarySites() {
19		const [t] = useI18n();
20		const [siteDicts, setSiteDicts] = createSignal<SiteDictionary[]>([]);
21		const [pendingSites, setPendingSites] = createSignal<SiteDictionary[]>([]);
22		const [loading, setLoading] = createSignal(true);
23	
24		const [expanded, setExpanded] = createSignal<Set<string>>(new Set());
25		const [newWordBySite, setNewWordBySite] = createSignal<Record<string, string>>({});
26		const [addingSite, setAddingSite] = createSignal<Set<string>>(new Set());
27		const [editingWordId, setEditingWordId] = createSignal<string | null>(null);
28		const [editingWord, setEditingWord] = createSignal("");
29	
30		const fetchSiteDicts = async () => {
31			const result = await listSiteDictionaries();
32			if (Result.isOk(result)) {
33				setSiteDicts(result.value);
34				preloadFavicons(result.value.map((g) => g.domain));
35			}
36		};
37	
38		onMount(async () => {
39			capture("$pageview", { $current_url: "/dictionary/sites" });
40			setLoading(true);
41			await fetchSiteDicts();
42			setLoading(false);
43		});
44	
45		const allSiteGroups = createMemo(() => {
46			const persisted = siteDicts();
47			const persistedDomains = new Set(persisted.map((d) => d.domain));
48			const pending = pendingSites().filter((p) => !persistedDomains.has(p.domain));
49			return [...persisted, ...pending];
50		});
51	
52		const configuredDomains = createMemo(() => new Set(allSiteGroups().map((g) => g.domain)));
53	
54		const addSite = (domain: string) => {
55			if (configuredDomains().has(domain)) {
56				setExpanded((prev) => {
57					const next = new Set(prev);
58					next.add(domain);
59					return next;
60				});
61				return;
62			}
63			setPendingSites((prev) => [...prev, { domain, words: [] }]);
64			setExpanded((prev) => {
65				const next = new Set(prev);
66				next.add(domain);
67				return next;
68			});
69			capture("site_dictionary_site_added");
70		};
71	
72		const toggleExpanded = (domain: string) => {
73			setExpanded((prev) => {
74				const next = new Set(prev);
75				if (next.has(domain)) next.delete(domain);
76				else next.add(domain);
77				return next;
78			});
79		};
80	
81		const handleAddWord = async (group: SiteDictionary) => {
82			const word = (newWordBySite()[group.domain] ?? "").trim();
83			if (!word) return;
84			if (addingSite().has(group.domain)) return;
85	
86			setAddingSite((prev) => {
87				const next = new Set(prev);
88				next.add(group.domain);
89				return next;
90			});
91			const result = await addSiteDictionaryWord(group.domain, word);
92			if (Result.isOk(result)) {
93				capture("site_dictionary_word_added");
94				setNewWordBySite((prev) => ({ ...prev, [group.domain]: "" }));
95				setPendingSites((prev) => prev.filter((p) => p.domain !== group.domain));
96				await fetchSiteDicts();
97			}
98			setAddingSite((prev) => {
99				const next = new Set(prev);
100				next.delete(group.domain);
101				return next;
102			});
103		};
104	
105		const handleWordKeyDown = (e: KeyboardEvent, group: SiteDictionary) => {
106			if (e.key === "Enter") handleAddWord(group);
107		};
108	
109		const startEditWord = (wordId: string, word: string) => {
110			setEditingWordId(wordId);
111			setEditingWord(word);
112		};
113	
114		const cancelEditWord = () => {
115			setEditingWordId(null);
116			setEditingWord("");
117		};
118	
119		const handleEditWord = async (group: SiteDictionary, wordId: string) => {
120			const word = editingWord().trim();
121			if (!word) return;
122			capture("site_dictionary_word_edited");
123			setSiteDicts(
124				siteDicts().map((g) =>
125					g.domain === group.domain
