18	const SKELETON_ROWS = Array.from({ length: 4 });
19	
20	export default function StylePerApp() {
21		const [t] = useI18n();
22		const cachedApps = getCachedInstalledApps();
23		const [installedApps, setInstalledApps] = createSignal<InstalledApp[]>(cachedApps ?? []);
24		const [instructions, setInstructions] = createSignal<AppInstruction[]>([]);
25		const [searchQuery, setSearchQuery] = createSignal("");
26		const [searchOpen, setSearchOpen] = createSignal(false);
27		const [highlightedIndex, setHighlightedIndex] = createSignal(0);
28		const [loading, setLoading] = createSignal(cachedApps === null);
29		let searchContainerRef: HTMLDivElement | undefined;
30		const optionRefs = new Map<number, HTMLButtonElement>();
31	
32		const fetchInstructions = async () => {
33			const result = await listAppInstructions();
34			if (Result.isOk(result)) setInstructions(result.value);
35		};
36	
37		onMount(async () => {
38			capture("$pageview", { $current_url: "/style/per-app" });
39			const [apps, instr] = await Promise.all([listInstalledApps(), listAppInstructions()]);
40			if (Result.isOk(apps)) setInstalledApps(apps.value);
41			if (Result.isOk(instr)) setInstructions(instr.value);
42			setLoading(false);
43		});
44	
45		const handleClickOutside = (e: MouseEvent) => {
46			if (searchContainerRef && !searchContainerRef.contains(e.target as Node)) {
47				setSearchOpen(false);
48			}
49		};
50	
51		createEffect(() => {
52			if (searchOpen()) {
53				document.addEventListener("click", handleClickOutside);
54			} else {
55				document.removeEventListener("click", handleClickOutside);
56			}
57		});
58	
59		onCleanup(() => {
60			document.removeEventListener("click", handleClickOutside);
61		});
62	
63		const configuredBundleIds = createMemo(() => new Set(instructions().map((i) => i.bundle_id)));
64	
65		const iconByBundleId = createMemo(() => {
66			const map = new Map<string, string>();
67			for (const app of installedApps()) {
68				if (app.icon_data_url) map.set(app.bundle_id, app.icon_data_url);
69			}
70			return map;
71		});
72	
73		const filteredApps = createMemo(() => {
74			const query = searchQuery().trim().toLowerCase();
75			const configured = configuredBundleIds();
76			return installedApps()
77				.filter((app) => !configured.has(app.bundle_id))
78				.filter((app) => {
79					if (!query) return true;
80					return (
81						app.name.toLowerCase().includes(query) || app.bundle_id.toLowerCase().includes(query)
82					);
83				})
84				.slice(0, 50);
85		});
86	
87		createEffect(() => {
88			filteredApps();
89			searchQuery();
90			setHighlightedIndex(0);
91		});
92	
93		createEffect(() => {
94			if (!searchOpen()) return;
95			const el = optionRefs.get(highlightedIndex());
96			el?.scrollIntoView({ block: "nearest" });
97		});
98	
99		const handleSearchKeyDown = (e: KeyboardEvent) => {
100			const items = filteredApps();
