113				const idx = Math.min(highlightedIndex(), items.length - 1);
114				const target = items[idx];
115				if (target) handleAddApp(target);
116			} else if (e.key === "Escape") {
117				if (!searchOpen()) return;
118				e.preventDefault();
119				setSearchOpen(false);
