172						<div class="flex items-center gap-3">
173							<Search class="w-4 h-4 text-txt-muted shrink-0" />
174							<input
175								type="text"
176								value={searchQuery()}
177								onInput={(e) => {
178									setSearchQuery(e.currentTarget.value);
179									setSearchOpen(true);
180								}}
181								onFocus={() => setSearchOpen(true)}
182								onKeyDown={handleSearchKeyDown}
183								placeholder={t("appInstructions.searchPlaceholder")}
184								class="flex-1 bg-transparent text-txt-primary font-mono placeholder-txt-muted focus:outline-none"
185							/>
