1	import { Result } from "better-result";
2	import { For, Show, createMemo, createSignal, onMount } from "solid-js";
3	import AddSiteForm from "../components/AddSiteForm";
4	import SiteIcon from "../components/SiteIcon";
5	import StyleSelect from "../components/StyleSelect";
6	import { useI18n } from "../i18n";
7	import {
8		type AppStyle,
9		type SiteStyle,
10		deleteSiteStyle,
11		listSiteStyles,
12		setSiteStyle,
13	} from "../lib/commands/apps";
14	import { preloadFavicons } from "../lib/favicons";
15	import { capture } from "../lib/posthog";
16	
17	export default function StylePerSite() {
18		const [t] = useI18n();
19		const [sites, setSites] = createSignal<SiteStyle[]>([]);
20		const [loading, setLoading] = createSignal(true);
21	
22		const fetchSites = async () => {
23			const result = await listSiteStyles();
24			if (Result.isOk(result)) {
25				setSites(result.value);
26				preloadFavicons(result.value.map((s) => s.domain));
27			}
28		};
29	
30		onMount(async () => {
31			capture("$pageview", { $current_url: "/style/sites" });
32			setLoading(true);
33			await fetchSites();
34			setLoading(false);
35		});
36	
37		const configuredDomains = createMemo(() => new Set(sites().map((s) => s.domain)));
38	
39		const addSite = async (domain: string) => {
40			if (configuredDomains().has(domain)) return;
41			const result = await setSiteStyle(domain, "default");
42			if (Result.isError(result)) return;
43			capture("site_style_added", { style: "default" });
44			await fetchSites();
45		};
46	
47		const handleChangeStyle = async (site: SiteStyle, style: AppStyle) => {
48			setSites(sites().map((s) => (s.id === site.id ? { ...s, style } : s)));
49			const result = await setSiteStyle(site.domain, style);
50			if (Result.isOk(result)) capture("site_style_changed", { style });
51			else await fetchSites();
52		};
53	
54		const handleDelete = async (id: string) => {
55			capture("site_style_deleted");
56			setSites(sites().filter((s) => s.id !== id));
57			const result = await deleteSiteStyle(id);
58			if (Result.isError(result)) await fetchSites();
59		};
60	
61		const styleLabel = (style: AppStyle) => {
62			switch (style) {
63				case "professional":
64					return t("appInstructions.styles.professional");
65				case "casual":
66					return t("appInstructions.styles.casual");
67				case "agents":
68					return t("appInstructions.styles.agents");
69				case "default":
70					return t("appInstructions.styles.default");
71			}
72		};
73	
74		return (
75			<div>
76				<div class="mb-4 flex items-center justify-between">
77					<p class="text-txt-muted font-mono text-xs">{t("style.perSiteDescription")}</p>
78					<Show when={sites().length > 0}>
79						<span class="text-txt-muted font-mono text-xs uppercase">
80							{t("dictionary.siteCount").replace("{count}", String(sites().length))}
81						</span>
82					</Show>
83				</div>
84	
85				<AddSiteForm onAdd={addSite} />
86	
87				<Show when={!loading() && sites().length === 0}>
88					<div class="bg-th-surface border border-border p-12 flex flex-col items-center justify-center text-center">
89						<div class="font-mono text-txt-muted text-sm mb-4">
90							<span class="text-ac">[INFO]</span> NO_SITES_CONFIGURED
91						</div>
92						<p class="text-txt-secondary font-mono text-xs uppercase tracking-wide">
93							{t("style.perSiteEmptyState")}
94						</p>
95						<p class="text-txt-muted font-mono text-xs mt-2 max-w-sm">
96							{t("style.perSiteEmptyStateDescription")}
97						</p>
98					</div>
99				</Show>
100	
101				<Show when={!loading() && sites().length > 0}>
102					<div class="space-y-1">
