import { Result } from "better-result";
import { For, Show, createSignal, onMount } from "solid-js";
import { useI18n } from "../i18n";
import {
	type DictionaryWord,
	addDictionaryWord,
	deleteDictionaryWord,
	listDictionaryWords,
	updateDictionaryWord,
} from "../lib/commands/dictionary";
import { capture } from "../lib/posthog";

export default function DictionaryDefault() {
	const [t] = useI18n();
	const [words, setWords] = createSignal<DictionaryWord[]>([]);
	const [newWord, setNewWord] = createSignal("");
	const [adding, setAdding] = createSignal(false);
	const [editingId, setEditingId] = createSignal<string | null>(null);
	const [editingWord, setEditingWord] = createSignal("");

	const fetchWords = async () => {
		const result = await listDictionaryWords();
		if (Result.isOk(result)) setWords(result.value);
	};

	onMount(() => {
		capture("$pageview", { $current_url: "/dictionary" });
