1	import { Result } from "better-result";
2	import { Search } from "lucide-solid";
3	import { For, Show, createEffect, createMemo, createSignal, onCleanup, onMount } from "solid-js";
4	import StyleSelect from "../components/StyleSelect";
5	import { useI18n } from "../i18n";
6	import {
7		type AppInstruction,
8		type AppStyle,
9		type InstalledApp,
10		deleteAppInstruction,
11		getCachedInstalledApps,
12		listAppInstructions,
13		listInstalledApps,
14		setAppInstruction,
15	} from "../lib/commands/apps";
16	import { capture } from "../lib/posthog";
17	
18	const SKELETON_ROWS = Array.from({ length: 4 });
19	
20	export default function StylePerApp() {
21		const [t] = useI18n();
22		const cachedApps = getCachedInstalledApps();
23		const [installedApps, setInstalledApps] = createSignal<InstalledApp[]>(cachedApps ?? []);
24		const [instructions, setInstructions] = createSignal<AppInstruction[]>([]);
25		const [searchQuery, setSearchQuery] = createSignal("");
26		const [searchOpen, setSearchOpen] = createSignal(false);
27		const [highlightedIndex, setHighlightedIndex] = createSignal(0);
28		const [loading, setLoading] = createSignal(cachedApps === null);
29		let searchContainerRef: HTMLDivElement | undefined;
30		const optionRefs = new Map<number, HTMLButtonElement>();
31	
32		const fetchInstructions = async () => {
33			const result = await listAppInstructions();
34			if (Result.isOk(result)) setInstructions(result.value);
35		};
36	
37		onMount(async () => {
38			capture("$pageview", { $current_url: "/style/per-app" });
39			const [apps, instr] = await Promise.all([listInstalledApps(), listAppInstructions()]);
40			if (Result.isOk(apps)) setInstalledApps(apps.value);
41			if (Result.isOk(instr)) setInstructions(instr.value);
42			setLoading(false);
43		});
44	
45		const handleClickOutside = (e: MouseEvent) => {
46			if (searchContainerRef && !searchContainerRef.contains(e.target as Node)) {
47				setSearchOpen(false);
48			}
49		};
50	
51		createEffect(() => {
52			if (searchOpen()) {
53				document.addEventListener("click", handleClickOutside);
54			} else {
55				document.removeEventListener("click", handleClickOutside);
56			}
57		});
58	
59		onCleanup(() => {
60			document.removeEventListener("click", handleClickOutside);
61		});
62	
63		const configuredBundleIds = createMemo(() => new Set(instructions().map((i) => i.bundle_id)));
64	
65		const iconByBundleId = createMemo(() => {
66			const map = new Map<string, string>();
67			for (const app of installedApps()) {
68				if (app.icon_data_url) map.set(app.bundle_id, app.icon_data_url);
69			}
70			return map;
71		});
72	
73		const filteredApps = createMemo(() => {
74			const query = searchQuery().trim().toLowerCase();
75			const configured = configuredBundleIds();
76			return installedApps()
77				.filter((app) => !configured.has(app.bundle_id))
78				.filter((app) => {
79					if (!query) return true;
80					return (
81						app.name.toLowerCase().includes(query) || app.bundle_id.toLowerCase().includes(query)
82					);
83				})
84				.slice(0, 50);
85		});
86	
87		createEffect(() => {
88			filteredApps();
89			searchQuery();
90			setHighlightedIndex(0);
91		});
92	
93		createEffect(() => {
94			if (!searchOpen()) return;
95			const el = optionRefs.get(highlightedIndex());
96			el?.scrollIntoView({ block: "nearest" });
97		});
98	
99		const handleSearchKeyDown = (e: KeyboardEvent) => {
100			const items = filteredApps();
101			if (e.key === "ArrowDown") {
102				e.preventDefault();
103				setSearchOpen(true);
104				if (items.length === 0) return;
105				setHighlightedIndex((i) => Math.min(items.length - 1, i + 1));
106			} else if (e.key === "ArrowUp") {
107				e.preventDefault();
108				if (items.length === 0) return;
109				setHighlightedIndex((i) => Math.max(0, i - 1));
110			} else if (e.key === "Enter") {
111				if (!searchOpen() || items.length === 0) return;
112				e.preventDefault();
113				const idx = Math.min(highlightedIndex(), items.length - 1);
114				const target = items[idx];
115				if (target) handleAddApp(target);
116			} else if (e.key === "Escape") {
117				if (!searchOpen()) return;
118				e.preventDefault();
119				setSearchOpen(false);
120			}
121		};
122	
123		const handleAddApp = async (app: InstalledApp) => {
124			const result = await setAppInstruction(app.bundle_id, app.name, "default");
125			if (Result.isError(result)) return;
126			capture("app_instruction_added", { style: "default" });
127			setSearchQuery("");
128			setSearchOpen(false);
129			await fetchInstructions();
130		};
131	
132		const handleChangeStyle = async (instruction: AppInstruction, style: AppStyle) => {
133			setInstructions(instructions().map((i) => (i.id === instruction.id ? { ...i, style } : i)));
134			const result = await setAppInstruction(instruction.bundle_id, instruction.app_name, style);
135			if (Result.isOk(result)) capture("app_instruction_style_changed", { style });
136			else await fetchInstructions();
137		};
138	
139		const handleDelete = async (id: string) => {
140			capture("app_instruction_deleted");
141			setInstructions(instructions().filter((i) => i.id !== id));
142			const result = await deleteAppInstruction(id);
143			if (Result.isError(result)) await fetchInstructions();
144		};
145	
146		const styleLabel = (style: AppStyle) => {
147			switch (style) {
148				case "professional":
149					return t("appInstructions.styles.professional");
150				case "casual":
151					return t("appInstructions.styles.casual");
152				case "agents":
153					return t("appInstructions.styles.agents");
154				case "default":
155					return t("appInstructions.styles.default");
156			}
157		};
158	
159		return (
160			<div>
161				<div class="mb-4 flex items-center justify-between">
162					<p class="text-txt-muted font-mono text-xs">{t("appInstructions.description")}</p>
163					<Show when={instructions().length > 0}>
164						<span class="text-txt-muted font-mono text-xs uppercase">
165							{t("appInstructions.appCount").replace("{count}", String(instructions().length))}
166						</span>
167					</Show>
168				</div>
169	
170				<div ref={searchContainerRef} class="relative mb-6">
171					<div class="bg-th-surface border border-border p-4">
172						<div class="flex items-center gap-3">
173							<Search class="w-4 h-4 text-txt-muted shrink-0" />
174							<input
175								type="text"
176								value={searchQuery()}
177								onInput={(e) => {
178									setSearchQuery(e.currentTarget.value);
179									setSearchOpen(true);
180								}}
181								onFocus={() => setSearchOpen(true)}
182								onKeyDown={handleSearchKeyDown}
183								placeholder={t("appInstructions.searchPlaceholder")}
184								class="flex-1 bg-transparent text-txt-primary font-mono placeholder-txt-muted focus:outline-none"
185							/>
186						</div>
187					</div>
188	
189					<Show when={searchOpen()}>
190						<div class="absolute z-50 w-full mt-1 bg-th-surface border border-border-strong max-h-72 overflow-auto">
191							<Show
192								when={!loading()}
193								fallback={<For each={SKELETON_ROWS}>{() => <AppRowSkeleton />}</For>}
194							>
195								<Show
196									when={filteredApps().length > 0}
197									fallback={
198										<div class="px-4 py-3 font-mono text-xs text-txt-muted uppercase tracking-wide">
199											{installedApps().length === 0
200												? t("appInstructions.noAppsDetected")
201												: t("appInstructions.noMatches")}
202										</div>
203									}
204								>
205									<For each={filteredApps()}>
206										{(app, index) => (
207											<button
208												type="button"
209												ref={(el) => optionRefs.set(index(), el)}
210												onClick={() => handleAddApp(app)}
211												onMouseEnter={() => setHighlightedIndex(index())}
212												class={`w-full px-4 py-2.5 text-left transition-colors font-mono text-sm flex items-center gap-3 ${
213													highlightedIndex() === index() ? "bg-th-hover" : ""
214												}`}
215											>
216												<AppIcon src={app.icon_data_url} alt={app.name} />
217												<div class="flex flex-col gap-0.5 min-w-0 flex-1">
218													<span class="text-txt-primary truncate">{app.name}</span>
219													<span class="text-txt-muted text-xs truncate">{app.bundle_id}</span>
220												</div>
221											</button>
222										)}
223									</For>
224								</Show>
225							</Show>
226						</div>
227					</Show>
228				</div>
229	
230				<Show when={loading()}>
231					<div class="space-y-1">
232						<For each={SKELETON_ROWS}>{() => <AppRowSkeleton bordered />}</For>
233					</div>
234				</Show>
235	
236				<Show when={!loading() && instructions().length === 0}>
237					<div class="bg-th-surface border border-border p-12 flex flex-col items-center justify-center text-center">
238						<div class="font-mono text-txt-muted text-sm mb-4">
239							<span class="text-ac">[INFO]</span> NO_APPS_CONFIGURED
240						</div>
241						<p class="text-txt-secondary font-mono text-xs uppercase tracking-wide">
242							{t("appInstructions.emptyState")}
243						</p>
244						<p class="text-txt-muted font-mono text-xs mt-2 max-w-sm">
245							{t("appInstructions.emptyStateDescription")}
246						</p>
247					</div>
248				</Show>
249	
250				<Show when={!loading() && instructions().length > 0}>
251					<div class="space-y-1">
252						<For each={instructions()}>
253							{(instruction) => (
254								<div class="bg-th-surface border border-border px-4 py-3 flex items-center justify-between gap-3 group hover:border-border-strong transition-colors">
255									<AppIcon
256										src={iconByBundleId().get(instruction.bundle_id) ?? null}
257										alt={instruction.app_name}
258									/>
259									<div class="flex flex-col min-w-0 flex-1">
260										<span class="text-txt-primary font-mono truncate">{instruction.app_name}</span>
261										<span class="text-txt-muted font-mono text-xs truncate">
262											{instruction.bundle_id}
263										</span>
264									</div>
265									<StyleSelect
266										value={instruction.style}
267										labelFor={styleLabel}
268										onChange={(style) => handleChangeStyle(instruction, style)}
269									/>
270									<button
271										type="button"
272										onClick={() => handleDelete(instruction.id)}
273										class="text-txt-muted hover:text-ac opacity-0 group-hover:opacity-100 transition-all font-mono text-xs uppercase tracking-wider"
274										title={t("appInstructions.delete")}
275									>
276										[DEL]
277									</button>
278								</div>
279							)}
280						</For>
281					</div>
282				</Show>
283			</div>
284		);
285	}
