307		);
308	}
309	
310	interface AppIconProps {
311		src: string | null;
312		alt: string;
313	}
314	
315	function AppIcon(props: AppIconProps) {
316		return (
317			<Show
318				when={props.src}
319				fallback={
320					<div class="w-8 h-8 shrink-0 bg-th-input border border-border flex items-center justify-center text-txt-muted font-mono text-xs">
321						{props.alt.charAt(0).toUpperCase()}
322					</div>
323				}
324			>
325				{(src) => <img src={src()} alt={props.alt} class="w-8 h-8 shrink-0" draggable={false} />}
326			</Show>
327		);
328	}
